package ru.reader.rsvp;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.*;

/** Offline, short-form collapsible in-app manual. */
public class ActivityInfo extends NavigationActivity {
    private int bg,fg;
    private String targetSection="";
    private ScrollView scrollView;
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable background(int color){GradientDrawable gd=new GradientDrawable();gd.setColor(color);gd.setCornerRadius(dp(12));return gd;}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg);return t;}
    @Override public void onCreate(Bundle state){super.onCreate(state);SharedPreferences prefs=getSharedPreferences("reader",0);
        bg=prefs.getInt("bg",0xfff3e7d5);fg=prefs.getInt("fg",0xff30221e);
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);root.setPadding(dp(16),dp(22),dp(16),dp(12));setContentView(root);SafeSystemBars.matchBackground(this,bg);
        TextView title=text("☰   Справка",24);title.setPadding(dp(2),dp(8),0,dp(18));title.setOnClickListener(v->UniversalDrawer.show(this));root.addView(title);
        targetSection=getIntent().getStringExtra("help_section");
        if(targetSection==null)targetSection="";
        ScrollView scroll=new ScrollView(this);scrollView=scroll;
        root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout entries=new LinearLayout(this);entries.setOrientation(1);scroll.addView(entries);
        String customBody=getIntent().getStringExtra("help_body");
        if(customBody!=null&&!customBody.isEmpty()&&!targetSection.isEmpty()){
            section(entries,targetSection,customBody);
        }
        section(entries,"Библиотека", "Откройте библиотеку, чтобы добавить книгу EPUB или FB2, выбрать обложку или продолжить чтение с сохранённого места. Для открытия книги просто коснитесь её обложки.");
        section(entries,"Обычное чтение", "Нажмите на книгу в библиотеке. Размер и шрифт текста меняются в настройках. Для выбора места чтения используйте оглавление или коснитесь нужного фрагмента.");
        section(entries,"Скоростное чтение", "Откройте книгу и выберите режим скоростного чтения. Настройте темп, нажмите воспроизведение и следите за сменой слов. В любой момент можно поставить на паузу.");
        section(entries,"Аудиокниги", "Добавьте аудиокнигу или папку с аудиофайлами, выберите нужную главу и нажмите воспроизведение. Приложение запомнит место остановки. Скорость и таймер сна настраиваются в плеере.");
        section(entries,"Системные голоса TTS", "В режиме озвучки можно выбрать установленный на устройстве голос. Нажмите прослушивание примера, чтобы подобрать удобный тембр и скорость.");
        section(entries,"Microsoft Edge TTS", "Выберите Edge TTS в плеере озвучки. Для подготовки новых глав потребуется интернет. При первом использовании выберите папку сохранения. Её можно изменить в настройках аудио. Готовые главы останутся в выбранной папке и их можно будет слушать без подключения к интернету.\n\nВ меню готовой книги в разделе «Загрузки» выберите «Перенести в аудиокниги», чтобы добавить MP3 в аудиотеку. Приложение создаст папку с названием книги и скопирует туда только звуковые файлы. Исходная озвучка и подсветка текста сохранятся.");
        section(entries,"Офлайн-прослушивание", "Сначала подготовьте озвучку нужных глав, пока есть интернет. После завершения загрузки эти главы можно воспроизводить без сети. Если новая глава ещё не подготовлена, для её озвучки потребуется подключение.");
        section(entries,"Словарь Edge TTS", "Если голос неправильно произносит слово, откройте словарь Edge TTS и добавьте собственное правило. Можно заменить слово или указать ударение. Нажмите «Прослушать», чтобы проверить звучание перед сохранением. Оригинальный текст книги не изменится.");
        section(entries,"Регулярные выражения словаря Edge TTS", "Для обычного исправления произношения достаточно замены слова. Дополнительный режим «Регулярное выражение» предназначен для сложных правил. Если вы не знакомы с этим режимом, его можно не включать. Проверяйте каждую замену кнопкой предварительного прослушивания.");
        section(entries,"Скачать по ссылке", "Вставьте ссылку на файл или несколько ссылок, каждую с новой строки. Нажмите проверку, выберите нужные файлы и папку назначения, затем начните загрузку. Поддерживаемые файлы можно открыть в библиотеке после завершения.");
        section(entries,"Поиск аудиокниг и манги", "Откройте поиск, найдите произведение, отметьте нужные главы и нажмите загрузку. Готовые аудиокниги появятся в аудиотеке, а манга — в комиксотеке.");
        section(entries,"Цвет выделения", "Выберите понравившийся цвет для выделенных строк и активных элементов интерфейса. Можно использовать цвет темы или настроить собственный.");
        section(entries,"Загрузки", "В разделе «Загрузки» видны текущие и завершённые скачивания. Откройте запись, чтобы посмотреть её состояние, приостановить загрузку или продолжить её. Готовую запись можно смахнуть вправо или отправить в архив через меню с тремя точками.\n\nВ архиве доступны поиск, сортировка, восстановление и удаление. «Очистить архив» убирает записи списка, но сохраняет файлы. Кнопка корзины удаляет выбранные скачанные файлы после подтверждения.");
        section(entries,"Загрузка озвучки", "Откройте книгу в «Загрузке озвучки», чтобы подготовить её для прослушивания. Нажмите на отдельную главу или «Подготовить все». Нажмите «Продолжить», чтобы загрузить оставшиеся главы по порядку; уже готовые главы сохранятся. Общая шкала показывает подготовку всей книги. Когда все главы готовы, появятся 100% и «Завершено».\n\nВ меню главы можно повторить загрузку, удалить её файлы или объединить готовые части в один MP3. Если вы одновременно слушаете другую главу, подготовка может немного подождать.");
        section(entries,"Чтейцо и награды", "Чтейцо — ваш книжный спутник. Читайте и слушайте книги, чтобы открывать награды и наблюдать, как он растёт. Питомца можно включать и выключать в настройках. Даже когда Чтейцо выключено, статистика и мини-игра «Рыбалка» остаются доступны. Нажмите «Игры» внизу статистики рыбалки.");
        section(entries,"Чтейцо — Рыбалка", "Откройте статистику рыбалки и нажмите «Игры». Для заброса удерживайте палец и отпустите, когда указатель окажется в зелёной зоне. После приводнения медленно подтягивайте поплавок. При поклёвке отпустите палец и нажмите снова, чтобы подсечь рыбу.\n\nВо время вываживания удерживайте палец, чтобы поднимать цветную зону, и отпускайте, чтобы опускать. Старайтесь удерживать рыбу внутри зоны, пока шкала улова не заполнится. Более тяжёлая рыба сопротивляется немного сильнее. За улов можно получить опыт и игровое золото. Наживки пополняются за чтение и прослушивание.");
        section(entries,"Чтейцо — Рыбалка: редкость и награды", "В игре встречаются обычные, необычные, редкие, легендарные и мифические рыбы. Чем реже рыба, тем интереснее улов. Иногда встречаются мерцающие экземпляры — за них начисляется больше золота.\n\nВ магазине можно приобрести улучшенные удочки. Они открывают доступ к более редкой и крупной рыбе. Лучшей удочкой можно поймать мифическую рыбу весом до 20 кг. За первую мифическую рыбу открывается награда «Мифический улов». Результаты и рекорды сохраняются в разделе «Улов».");
        section(entries,"Редактирование меню", "Включите редактирование меню в настройках, если хотите изменить расположение его элементов. После настройки вернитесь к обычному режиму.");
        section(entries,"Чтейцо — описание", "Чтейцо — маленький спутник ваших книжных приключений. Ему нравятся истории и минуты чтения. Заглядывайте к нему, чтобы увидеть новые эмоции и изменения.");
        section(entries,"Справка об озвучке", "Откройте режим «Озвучка», выберите голос и скорость. Вы можете слушать книгу и следить за выделением произносимого текста.");
        section(entries,"Задержка старта", "Задайте небольшую задержку перед началом воспроизведения, чтобы успеть приготовиться к чтению.");
        section(entries,"Подсветка текста", "Настройте яркость фона выделенного слова или предложения. Слабое выделение менее заметно, сильное лучше видно на экране.");
        section(entries,"Скоростное чтение — порции", "Выберите, сколько слов будет показываться одновременно. Начните с небольшого количества и постепенно подберите удобный вариант.");
        section(entries,"Скоростное чтение — фокус", "Включите фокус, чтобы удобнее следить взглядом за словами. Начальное слово можно выбрать касанием текста.");
        section(entries,"Выбор слова", "Нажмите кнопку выбора слова, затем коснитесь слова в тексте, с которого хотите начать чтение.");
        section(entries,"Режим Курсор", "В этом режиме можно выбирать слова прямо касанием текста и менять их оформление в настройках.");
        section(entries,"Цвет обычных кнопок", "Изменяет цвет обычных кнопок управления и навигации.");
        section(entries,"Цвет акцентных кнопок", "Изменяет цвет главных действий — например, воспроизведения и выбора режима.");
        section(entries,"Обновления", "Откройте пункт «Обновление» в боковом меню, чтобы проверить доступность новой версии приложения.");
    }
    void section(LinearLayout entries,String heading,String body){
        LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setBackground(background((Color.red(bg)+Color.green(bg)+Color.blue(bg))<360?0xff353b3a:0xfffff8ee));
        LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);entries.addView(panel,lp);
        TextView h=text(heading+"    ▾",17);h.setPadding(dp(14),dp(16),dp(14),dp(16));panel.addView(h);
        TextView content=text(body,15);content.setPadding(dp(14),0,dp(14),dp(17));content.setVisibility(View.GONE);panel.addView(content);
        if(heading.equals(targetSection)){
            content.setVisibility(View.VISIBLE);h.setText(heading+"    ▴");
            scrollView.post(()->scrollView.smoothScrollTo(0,panel.getTop()));
        }
        h.setOnClickListener(v->{boolean show=content.getVisibility()!=View.VISIBLE;content.setVisibility(show?View.VISIBLE:View.GONE);h.setText(heading+(show?"    ▴":"    ▾"));});
    }
}
